import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_CPP_SRC = r"""
#include <torch/extension.h>

torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding);
"""

_CUDA_SRC = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_runtime.h>

namespace {

constexpr int IN_CHANNELS = 3;
constexpr int OUT_CHANNELS = 96;
constexpr int KERNEL_H = 11;
constexpr int KERNEL_W = 11;
constexpr int STRIDE = 4;
constexpr int PADDING = 2;
constexpr int GEMM_K = IN_CHANNELS * KERNEL_H * KERNEL_W;

constexpr int TILE_M = 128;
constexpr int TILE_N = OUT_CHANNELS;
constexpr int TILE_K = 32;
constexpr int THREADS = 256;
constexpr int AS_FLOATS = TILE_N * (TILE_K + 1);
constexpr int BS_FLOATS = TILE_K * (TILE_M + 4);
constexpr int SMEM_FLOATS = 2 * (AS_FLOATS + BS_FLOATS);
constexpr int SMEM_BYTES = SMEM_FLOATS * 4;

__device__ __forceinline__ void cp_async_commit() {
    asm volatile("cp.async.commit_group;\n" :: : "memory");
}
template <int N>
__device__ __forceinline__ void cp_async_wait() {
    asm volatile("cp.async.wait_group %0;\n" :: "n"(N) : "memory");
}
__device__ __forceinline__ void cp_async_4(void* smem_dst, const void* gmem_src, int src_size) {
    const unsigned dst = static_cast<unsigned>(__cvta_generic_to_shared(smem_dst));
    asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;\n"
                 :: "r"(dst), "l"(gmem_src), "r"(src_size) : "memory");
}
__device__ __forceinline__ void load_tile_async(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const int* __restrict__ s_n,
    const int* __restrict__ s_oh,
    const int* __restrict__ s_ow,
    const int* __restrict__ s_c,
    const int* __restrict__ s_kh,
    const int* __restrict__ s_kw,
    int k0,
    int height,
    int width,
    int tid,
    float* __restrict__ a_dst,
    float* __restrict__ b_dst) {
    constexpr int A_ELEMS = TILE_N * TILE_K / THREADS;
    constexpr int B_ELEMS = TILE_K * TILE_M / THREADS;
#pragma unroll
    for (int i = 0; i < A_ELEMS; ++i) {
        const int idx = tid + i * THREADS;
        const int row = idx >> 5;
        const int kk = idx & 31;
        const int k = k0 + kk;
        const bool valid = k < GEMM_K;
        const float* src = weight + row * GEMM_K + (valid ? k : 0);
        cp_async_4(a_dst + row * (TILE_K + 1) + kk, src, valid ? 4 : 0);
    }
#pragma unroll
    for (int i = 0; i < B_ELEMS; ++i) {
        const int idx = tid + i * THREADS;
        const int kk = idx / TILE_M;
        const int col = idx - kk * TILE_M;
        const int k = k0 + kk;
        bool valid = false;
        const float* src = input;
        if (k < GEMM_K) {
            const int n = s_n[col];
            if (n >= 0) {
                const int ih = s_oh[col] * STRIDE + s_kh[k] - PADDING;
                const int iw = s_ow[col] * STRIDE + s_kw[k] - PADDING;
                if (ih >= 0 && ih < height && iw >= 0 && iw < width) {
                    src = input + ((n * IN_CHANNELS + s_c[k]) * height + ih) * width + iw;
                    valid = true;
                }
            }
        }
        cp_async_4(b_dst + kk * (TILE_M + 4) + col, src, valid ? 4 : 0);
    }
}
__global__ void __launch_bounds__(THREADS, 2) conv2d_implicit_gemm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int height,
    int width,
    int out_height,
    int out_width,
    int spatial_per_image,
    int total_m) {
    constexpr int A_ELEMS = TILE_N * TILE_K / THREADS;
    constexpr int B_ELEMS = TILE_K * TILE_M / THREADS;
    extern __shared__ float smem[];
    float* const As = smem;
    float* const Bs = smem + 2 * AS_FLOATS;
    __shared__ int s_n[TILE_M];
    __shared__ int s_oh[TILE_M];
    __shared__ int s_ow[TILE_M];
    __shared__ int s_c[GEMM_K];
    __shared__ int s_kh[GEMM_K];
    __shared__ int s_kw[GEMM_K];
    const int tid = threadIdx.x;
    const int tx = tid & 15;
    const int ty = tid >> 4;
    const int m_tile = blockIdx.x * TILE_M;
    const int local_m0 = (tx & 7) * 4 + (tx >> 3) * 64;
    const int local_oc0 = ty * 6;
    if (tid < TILE_M) {
        const int m = m_tile + tid;
        if (m < total_m) {
            const int n = m / spatial_per_image;
            const int rem = m - n * spatial_per_image;
            const int oh = rem / out_width;
            const int ow = rem - oh * out_width;
            s_n[tid] = n;
            s_oh[tid] = oh;
            s_ow[tid] = ow;
        } else {
            s_n[tid] = -1;
            s_oh[tid] = 0;
            s_ow[tid] = 0;
        }
    }
    for (int k = tid; k < GEMM_K; k += THREADS) {
        const int c = k / (KERNEL_H * KERNEL_W);
        const int k_rem = k - c * (KERNEL_H * KERNEL_W);
        const int kh = k_rem / KERNEL_W;
        s_c[k] = c;
        s_kh[k] = kh;
        s_kw[k] = k_rem - kh * KERNEL_W;
    }
    __syncthreads();
    load_tile_async(input, weight, s_n, s_oh, s_ow, s_c, s_kh, s_kw,
                    0, height, width, tid, As, Bs);
    cp_async_commit();
    float acc[6][8];
#pragma unroll
    for (int i = 0; i < 6; ++i) {
        const float b = bias[local_oc0 + i];
#pragma unroll
        for (int j = 0; j < 8; ++j) {
            acc[i][j] = b;
        }
    }
    int buf = 0;
    for (int k0 = 0; k0 < GEMM_K; k0 += TILE_K, buf ^= 1) {
        const float* a_cur = As + buf * AS_FLOATS;
        const float* b_cur = Bs + buf * BS_FLOATS;
        const int k_next = k0 + TILE_K;
        const bool has_next = k_next < GEMM_K;
        if (has_next) {
            load_tile_async(input, weight, s_n, s_oh, s_ow, s_c, s_kh, s_kw,
                            k_next, height, width, tid,
                            As + (buf ^ 1) * AS_FLOATS, Bs + (buf ^ 1) * BS_FLOATS);
            cp_async_commit();
            cp_async_wait<1>();
        } else {
            cp_async_wait<0>();
        }
        __syncthreads();
#pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            float a_vals[6];
            float b_vals[8];
#pragma unroll
            for (int i = 0; i < 6; ++i) {
                a_vals[i] = a_cur[(local_oc0 + i) * (TILE_K + 1) + kk];
            }
            const float4 b_vec0 = *reinterpret_cast<const float4*>(&b_cur[kk * (TILE_M + 4) + local_m0]);
            const float4 b_vec1 = *reinterpret_cast<const float4*>(&b_cur[kk * (TILE_M + 4) + local_m0 + 32]);
            b_vals[0] = b_vec0.x;
            b_vals[1] = b_vec0.y;
            b_vals[2] = b_vec0.z;
            b_vals[3] = b_vec0.w;
            b_vals[4] = b_vec1.x;
            b_vals[5] = b_vec1.y;
            b_vals[6] = b_vec1.z;
            b_vals[7] = b_vec1.w;
#pragma unroll
            for (int i = 0; i < 6; ++i) {
#pragma unroll
                for (int j = 0; j < 8; ++j) {
                    acc[i][j] = fmaf(a_vals[i], b_vals[j], acc[i][j]);
                }
            }
        }
        __syncthreads();
    }
#pragma unroll
    for (int i = 0; i < 6; ++i) {
        const int oc = local_oc0 + i;
#pragma unroll
        for (int j = 0; j < 8; ++j) {
            const int local_m = local_m0 + (j & 3) + ((j & 4) << 3);
            const int n = s_n[local_m];
            if (n >= 0) {
                const int oh = s_oh[local_m];
                const int ow = s_ow[local_m];
                output[((n * OUT_CHANNELS + oc) * out_height + oh) * out_width + ow] = acc[i][j];
            }
        }
    }
}

}  // namespace

torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

    TORCH_CHECK(input.scalar_type() == at::kFloat, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");

    TORCH_CHECK(input.dim() == 4, "input must be NCHW");
    TORCH_CHECK(input.size(1) == IN_CHANNELS, "input must have 3 channels");

    TORCH_CHECK(weight.dim() == 4, "weight must have 4 dimensions");
    TORCH_CHECK(weight.size(0) == OUT_CHANNELS, "weight must have 96 output channels");
    TORCH_CHECK(weight.size(1) == IN_CHANNELS, "weight must have 3 input channels");
    TORCH_CHECK(weight.size(2) == KERNEL_H && weight.size(3) == KERNEL_W,
                "only an 11x11 kernel is supported");

    TORCH_CHECK(bias.defined() && bias.dim() == 1 && bias.size(0) == OUT_CHANNELS,
                "bias must have shape [96]");
    TORCH_CHECK(stride == STRIDE, "only stride 4 is supported");
    TORCH_CHECK(padding == PADDING, "only padding 2 is supported");

    const c10::cuda::CUDAGuard device_guard(input.device());

    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    auto bias_c = bias.contiguous();

    const int64_t batch = input_c.size(0);
    const int64_t height = input_c.size(2);
    const int64_t width = input_c.size(3);
    const int64_t out_height = (height + 2 * PADDING - KERNEL_H) / STRIDE + 1;
    const int64_t out_width = (width + 2 * PADDING - KERNEL_W) / STRIDE + 1;

    TORCH_CHECK(out_height > 0 && out_width > 0, "invalid output spatial dimensions");

    auto output = torch::empty(
        {batch, OUT_CHANNELS, out_height, out_width},
        input_c.options());

    const int spatial_per_image = static_cast<int>(out_height * out_width);
    const int total_m = static_cast<int>(batch * spatial_per_image);

    if (total_m > 0) {
        const dim3 block(THREADS);
        const dim3 grid((total_m + TILE_M - 1) / TILE_M);
        cudaStream_t stream = at::cuda::getCurrentCUDAStream();
        C10_CUDA_CHECK(cudaFuncSetAttribute(
            conv2d_implicit_gemm_kernel,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            SMEM_BYTES));
        conv2d_implicit_gemm_kernel<<<grid, block, SMEM_BYTES, stream>>>(
            input_c.data_ptr<float>(),
            weight_c.data_ptr<float>(),
            bias_c.data_ptr<float>(),
            output.data_ptr<float>(),
            static_cast<int>(height),
            static_cast<int>(width),
            static_cast<int>(out_height),
            static_cast<int>(out_width),
            spatial_per_image,
            total_m);

        C10_CUDA_KERNEL_LAUNCH_CHECK();
    }

    return output;
}
"""

_conv_ext = load_inline(
    name="custom_alexnet_conv1",
    cpp_sources=[_CPP_SRC],
    cuda_sources=[_CUDA_SRC],
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(
            in_channels=3,
            out_channels=96,
            kernel_size=11,
            stride=4,
            padding=2,
        )

    def forward(self, x):
        return _conv_ext.conv2d_forward(
            x,
            self.conv1.weight,
            self.conv1.bias,
            self.conv1.stride[0],
            self.conv1.padding[0],
        )

